/**
 * Text animation utility using GSAP for performance
 * Creates an ethereal, 56k modem-style loading text effect
 */
import { gsap } from 'gsap';

// Get random value between min and max
const getRandomValue = (min, max) => {
  return min + Math.random() * (max - min);
};

// Get random boolean based on probability
const getRandomBool = (probability) => {
  return Math.random() < probability;
};

/**
 * Split text into spans for animation
 * @param {HTMLElement} element - Element containing text to split
 * @returns {HTMLSpanElement[]} Array of span elements
 */
const splitTextIntoSpans = (element) => {
  if (!element || !element.textContent) return [];

  // Store original element properties
  const originalHTML = element.innerHTML;
  const computedStyle = window.getComputedStyle(element);
  const originalColor = computedStyle.color;
  const originalFontSize = computedStyle.fontSize;
  const originalFontWeight = computedStyle.fontWeight;
  const originalFontFamily = computedStyle.fontFamily;

  // Save original text and create a wrapper
  const text = element.textContent;
  const wrapper = document.createElement('span');
  wrapper.classList.add('gsap-text-wrapper');
  wrapper.style.display = 'inline-block';

  // Create spans for each character
  const spans = [];
  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    const span = document.createElement('span');
    span.textContent = char === ' ' ? '\u00A0' : char; // Use non-breaking space for spaces
    span.style.display = 'inline-block';
    span.style.opacity = '0';
    span.classList.add('gsap-char');

    // Preserve original text styling
    span.style.color = originalColor;
    span.style.fontSize = originalFontSize;
    span.style.fontWeight = originalFontWeight;
    span.style.fontFamily = originalFontFamily;

    // Add special classes to some characters
    if (getRandomBool(0.08)) {
      span.classList.add('gsap-char-flicker');
    }
    if (getRandomBool(0.05)) {
      span.classList.add('gsap-char-glow');
    }

    wrapper.appendChild(span);
    spans.push(span);
  }

  // Replace element content with our spans
  element.innerHTML = '';
  element.appendChild(wrapper);

  // Store original HTML for potential cleanup
  wrapper.dataset.originalHtml = originalHTML;

  return spans;
};

/**
 * Reset element to its original state
 * @param {HTMLElement} element - Element to reset
 */
const resetElement = (element) => {
  if (!element) return;

  const wrapper = element.querySelector('.gsap-text-wrapper');
  if (wrapper && wrapper.dataset.originalHtml) {
    element.innerHTML = wrapper.dataset.originalHtml;
  }
};

/**
 * Animate a single element's text with character-by-character animation
 * @param {HTMLElement} element - Element to animate
 * @param {Object} options - Animation options
 */
export const animateText = (element, options = {}) => {
  if (!element) return;

  const defaults = {
    staggerRange: [0.01, 0.08],
    duration: 0.3,
    ease: "power2.out",
    delay: 0,
    blur: 3,
    y: 3,
    cleanup: true  // Whether to reset the element after animation
  };

  const settings = { ...defaults, ...options };

  // Skip certain elements
  if (element.classList.contains('no-animate') || 
      element.tagName === 'BUTTON' || 
      element.tagName === 'INPUT') {
    return;
  }

  // Reset element before animating (if it was previously animated)
  if (element.querySelector('.gsap-text-wrapper') && settings.cleanup) {
    resetElement(element);
  }

  // Split text into spans
  const spans = splitTextIntoSpans(element);
  if (!spans.length) return;

  // Create timeline for this element
  const timeline = gsap.timeline({
    delay: settings.delay,
    onComplete: () => {
      // Add special effects to some characters after the main animation
      spans.forEach(span => {
        if (span.classList.contains('gsap-char-flicker')) {
          gsap.to(span, {
            opacity: 0.7,
            duration: 0.2,
            repeat: -1,
            yoyo: true,
            ease: "none",
            repeatDelay: getRandomValue(1, 3)
          });
        }

        if (span.classList.contains('gsap-char-glow')) {
          const textShadow = "0 0 6px rgba(255, 255, 255, 0.5)";
          gsap.to(span, {
            textShadow,
            duration: 1.5,
            repeat: -1,
            yoyo: true,
            ease: "sine.inOut"
          });
        }
      });
    }
  });

  // Stagger amount based on text length
  const staggerAmount = getRandomValue(
    settings.staggerRange[0] * spans.length, 
    settings.staggerRange[1] * spans.length
  );

  // Animate each character with staggered delay
  timeline.to(spans, {
    opacity: 1,
    y: 0,
    duration: settings.duration,
    ease: settings.ease,
    stagger: {
      amount: staggerAmount,
      from: "start"
    },
    filter: "blur(0px)",
  }, 0);

  // Add blur effect for ethereal appearance
  timeline.fromTo(spans, 
    { 
      filter: `blur(${settings.blur}px)`,
      y: settings.y
    },
    { 
      filter: "blur(0px)",
      y: 0,
      duration: settings.duration * 1.2,
      ease: settings.ease,
      stagger: {
        amount: staggerAmount,
        from: "start"
      }
    }, 
    0
  );

  return timeline;
};

/**
 * Find and animate multiple text elements within a container
 * @param {HTMLElement} container - Container element
 * @param {Object} options - Animation options
 */
export const animateTextInContainer = (container, options = {}) => {
  if (!container) return;

  // Define selectors for elements to animate
  const targetSelectors = [
    'h1, h2, h3, h4, h5, h6',            // Headings
    'p',                                 // Paragraphs
    '.category-item > a',                // Category links
    'li',                                // List items
    '.sub-links a:not(.no-animate)'      // Sub navigation links
  ];

  // Exclude selectors that shouldn't be animated
  const excludeSelectors = options.excludeSelectors || [
    '.alien-title',
    '.no-animate',
    'button',
    'input',
    'textarea',
    '.gsap-text-wrapper'  // Prevent re-animating already animated text
  ];

  // Find all elements to animate
  let elementsToAnimate = [];
  targetSelectors.forEach(selector => {
    const elements = container.querySelectorAll(selector);
    elementsToAnimate = [...elementsToAnimate, ...Array.from(elements)];
  });

  // Filter out excluded elements
  elementsToAnimate = elementsToAnimate.filter(el => {
    return !excludeSelectors.some(selector => {
      if (el.matches && el.matches(selector)) return true;
      if (el.closest && el.closest(selector)) return true;
      return false;
    });
  });

  // Create master timeline
  const masterTimeline = gsap.timeline();

  // Batch elements by type for performance optimization
  const headings = elementsToAnimate.filter(el => /^H[1-6]$/.test(el.tagName));
  const paragraphs = elementsToAnimate.filter(el => el.tagName === 'P');
  const links = elementsToAnimate.filter(el => el.tagName === 'A');
  const listItems = elementsToAnimate.filter(el => el.tagName === 'LI');
  const others = elementsToAnimate.filter(el => {
    return !['H1', 'H2', 'H3', 'H4', 'H5', 'H6', 'P', 'A', 'LI'].includes(el.tagName);
  });

  // Animate different element types with appropriate timing
  // Headings first (with the most dramatic effect)
  headings.forEach((element, index) => {
    const elementTimeline = animateText(element, {
      ...options,
      delay: 0.05 * index,
      blur: 4,
      y: 5
    });

    if (elementTimeline) {
      masterTimeline.add(elementTimeline, 0);
    }
  });

  // Paragraphs with a slight delay
  paragraphs.forEach((element, index) => {
    const elementTimeline = animateText(element, {
      ...options,
      delay: 0.03 * index,
      blur: 2,
      staggerRange: [0.005, 0.02]
    });

    if (elementTimeline) {
      masterTimeline.add(elementTimeline, 0.2);
    }
  });

  // Links and list items with minimal delay
  [...links, ...listItems].forEach((element, index) => {
    const elementTimeline = animateText(element, {
      ...options,
      delay: 0.02 * index,
      blur: 2,
      staggerRange: [0.003, 0.015]
    });

    if (elementTimeline) {
      masterTimeline.add(elementTimeline, 0.3 + (index * 0.01));
    }
  });

  // Other elements
  others.forEach((element, index) => {
    const elementTimeline = animateText(element, {
      ...options,
      delay: 0.01 * index
    });

    if (elementTimeline) {
      masterTimeline.add(elementTimeline, 0.4);
    }
  });

  return masterTimeline;
};

/**
 * Add required CSS for animations
 */
const addAnimationStyles = () => {
  if (document.getElementById('gsap-text-styles')) return;

  const styleEl = document.createElement('style');
  styleEl.id = 'gsap-text-styles';
  styleEl.textContent = `
    .gsap-char {
      display: inline-block;
      transform-origin: center;
      opacity: 0;
      position: relative;
      white-space: pre;
    }

    /* Preserve line height for consistency */
    .gsap-text-wrapper {
      display: inline-block;
      position: relative;
      line-height: inherit;
    }

    /* Fix for punctuation spacing */
    .gsap-char:empty::before,
    .gsap-char:matches(.,;:!?'"()) {
      display: inline-block;
      width: auto;
    }
  `;

  document.head.appendChild(styleEl);
};

// Initialize styles on load
if (typeof document !== 'undefined') {
  addAnimationStyles();
}

/**
 * Main function to animate all content
 */
export const animateAllContent = () => {
  // Add styles
  if (typeof document !== 'undefined') {
    addAnimationStyles();
  }

  // Kill any running animations to prevent conflicts
  gsap.killTweensOf('.gsap-char');

  // Animate main content
  const mainContent = document.querySelector('.main-content');
  if (mainContent) {
    // First fade in the container as a whole
    gsap.fromTo(mainContent, 
      { opacity: 0.7 },
      { opacity: 1, duration: 0.4, ease: "power1.out" }
    );

    // Then animate text within
    animateTextInContainer(mainContent, {
      staggerRange: [0.01, 0.05],
      excludeSelectors: ['.alien-title', '.no-animate', 'button', 'input']
    });
  }

  // Create a fade-in effect for category items containers
  const categoryContainers = document.querySelectorAll('.categories, .subcategories, .category-links');
  if (categoryContainers.length) {
    gsap.fromTo(categoryContainers, 
      { opacity: 0, y: 10 },
      { opacity: 1, y: 0, duration: 0.5, ease: "power2.out", stagger: 0.1 }
    );
  }

  // Handle category items separately for better control
  const categoryItems = document.querySelectorAll('.category-item');
  if (categoryItems.length) {
    // Fade in the items
    gsap.fromTo(categoryItems, 
      { opacity: 0, y: 10 },
      { 
        opacity: 1, 
        y: 0, 
        duration: 0.4,
        stagger: 0.04,
        ease: "power2.out",
        onComplete: () => {
          // After items fade in, animate their text
          categoryItems.forEach((item, index) => {
            setTimeout(() => {
              const link = item.querySelector('a');
              if (link) animateText(link, { staggerRange: [0.002, 0.01], blur: 1 });

              const count = item.querySelector('.count');
              if (count) {
                setTimeout(() => {
                  animateText(count, { staggerRange: [0.002, 0.01], blur: 1 });
                }, 30);
              }
            }, index * 25);
          });
        }
      }
    );
  }
};

export default { animateText, animateTextInContainer, animateAllContent };
